async function commit(preflight){const {c,checkpoint}=await recorded(),v=await read(FOLDER+'/verify-state-a1/result.json');assert.equal(v.pass,true);assert.equal(v.inputsUnchanged,true);assert.equal(v.error,null);assert.equal(v.sourceCommit,c.sourceCommit);assert.deepEqual(v.result,checkpoint.result);assert.deepEqual(v.producer,await ref(HERE+'/checkpoint.mjs'));await refs(v.inputs);const report=await vjson(v.rawReport);assert.equal(report.pass,true);assert.equal(report.releaseReady,false);assert.deepEqual(report.errors,[]);const files=await walk(FOLDER),ignored=lines(git(['ls-files','--others','--ignored','--exclude-standard','--',FOLDER])).sort(),visible=files.filter(p=>!ignored.includes(p));assert.ok(ignored.every(p=>p.endsWith('.log')&&p.startsWith(FOLDER+'/actual/')),'Force-add only authenticated copied logs');assert.deepEqual(lines(git(['ls-files','--others','--exclude-standard'])).sort(),visible);const paths=[...GLOBALS,...files].sort(),inputs=await snap(paths);await assert.rejects(fs.stat(RUN+'/docs-commit.json'),{code:'ENOENT'});if(preflight){console.log(json({mode:'commit-preflight',writes:false,paths,ignoredCopiedLogs:ignored}));return;}git(['add','--',...GLOBALS,...visible]);if(ignored.length)git(['add','--force','--',...ignored]);assert.deepEqual(lines(git(['diff','--cached','--name-only'])).sort(),paths);git(['commit','-m','Record D238 local prerequisite-completion preview evidence']);const head=gt(['rev-parse','HEAD']);assert.equal(gt(['rev-parse',head+'^']),c.sourceCommit);assert.deepEqual(lines(git(['diff','--name-only',c.sourceCommit,head])).sort(),paths);assert.equal(gt(['status','--porcelain','--untracked-files=all']),'');assert.deepEqual(await snap(paths),inputs);const blobs=[];for(const r of inputs){const raw=await checked(r),blob=git(['cat-file','blob',head+':'+r.path]);if(!raw.equals(blob)){assert.ok(Buffer.from(raw.toString('utf8')).equals(raw)&&Buffer.from(blob.toString('utf8')).equals(blob));assert.equal(raw.toString('utf8').replaceAll('\r\n','\n'),blob.toString('utf8').replaceAll('\r\n','\n'));}blobs.push({path:r.path,workingSha256:r.sha256,gitBlobSha256:sha(blob),lineEndingOnly:!raw.equals(blob)});}await fresh(RUN+'/docs-commit.json',{pass:true,decision:'D238',sourceCommit:c.sourceCommit,checkpoint:head,result:checkpoint.result,verification:await ref(FOLDER+'/verify-state-a1/result.json'),producer:await ref(HERE+'/checkpoint.mjs'),inputs,blobs,clean:true,releaseReady:false});console.log(json({mode:'commit',checkpoint:head,receipt:await ref(RUN+'/docs-commit.json')}));}
