const [mode,...args]=process.argv.slice(2);if(mode==='record'){assert.ok(args.length===4||(args.length===5&&args[4]==='--preflight'));const [sourcePath,sourceSha,buildPath,buildSha]=args;await record({source:{path:norm(sourcePath),sha256:sourceSha},build:{path:norm(buildPath),sha256:buildSha}},args.length===5);}else if(mode==='verify'){assert.equal(args.length,0);await verify();}else if(mode==='commit'){assert.ok(args.length===0||(args.length===1&&args[0]==='--preflight'));await commit(args.length===1);}else throw Error('Usage: checkpoint.mjs record SOURCE_RECEIPT SOURCE_SHA BUILD_RECEIPT BUILD_SHA [--preflight] | verify | commit [--preflight]');
